`timescale 1ns/1ps
// Shared Tessera execution path: one arbiter dispatches each accepted command to
// either the vector ALU or tensor MAC tile; both return to one tagged completion FIFO.
module tessera_execution_system #(parameter integer N_CLIENTS=4,OP_W=3,TAG_W=8,DATA_W=16,ACC_W=32,DEPTH=4,CLIENT_W=(N_CLIENTS<=2)?1:$clog2(N_CLIENTS),COUNT_W=$clog2(DEPTH+1),REC_W=CLIENT_W+TAG_W+2+ACC_W,DEP_TAGS=16)(
input logic clk,rst_n,input logic [N_CLIENTS-1:0] req,input logic [N_CLIENTS*OP_W-1:0] op_bus,input logic [N_CLIENTS*TAG_W-1:0] tag_bus,input logic [N_CLIENTS-1:0] unit_select_bus,input logic [N_CLIENTS*DATA_W-1:0] operand_a_bus,operand_b_bus,input logic [N_CLIENTS*ACC_W-1:0] accumulator_bus,output logic [N_CLIENTS-1:0] grant,output logic completion_valid,input logic completion_ready,output logic [CLIENT_W-1:0] completion_client,output logic [TAG_W-1:0] completion_tag,output logic [1:0] completion_status,output logic [ACC_W-1:0] completion_result,output logic [COUNT_W-1:0] completion_occupancy);
logic cmd_valid,cmd_ready; logic [CLIENT_W-1:0] cmd_client; logic [OP_W-1:0] cmd_op; logic [TAG_W-1:0] cmd_tag; logic select_tensor; logic [DATA_W-1:0] a,b; logic signed [ACC_W-1:0] acc; logic v_ready,t_ready,v_done,t_done,v_done_ready,t_done_ready; logic [CLIENT_W-1:0] v_client,t_client; logic [TAG_W-1:0] v_tag,t_tag; logic [1:0] v_status,t_status; logic [DATA_W-1:0] v_result; logic signed [ACC_W-1:0] t_result; logic [REC_W-1:0] rec_in,rec_out; logic [COUNT_W-1:0] q_count; logic dep_alloc_ready,dep_known,dep_dup,dep_unknown; logic [N_CLIENTS*DEP_TAGS-1:0] dep_live; logic [$clog2(N_CLIENTS*DEP_TAGS+1)-1:0] dep_count;
tessera_dispatcher #(.N_CLIENTS(N_CLIENTS),.CLIENT_W(CLIENT_W),.OP_W(OP_W),.TAG_W(TAG_W)) arb(.clk(clk),.rst_n(rst_n),.req(req),.op_bus(op_bus),.tag_bus(tag_bus),.grant(grant),.cmd_valid(cmd_valid),.cmd_ready(cmd_ready),.cmd_client(cmd_client),.cmd_op(cmd_op),.cmd_tag(cmd_tag));
assign select_tensor=unit_select_bus[cmd_client]; assign a=operand_a_bus[cmd_client*DATA_W+:DATA_W]; assign b=operand_b_bus[cmd_client*DATA_W+:DATA_W]; assign acc=accumulator_bus[cmd_client*ACC_W+:ACC_W];
assign cmd_ready=(select_tensor?t_ready:v_ready)&&dep_alloc_ready;
tessera_vec_tile #(.CLIENT_W(CLIENT_W),.TAG_W(TAG_W),.DATA_W(DATA_W),.OP_W(OP_W)) vec(.clk(clk),.rst_n(rst_n),.cmd_valid(cmd_valid&&!select_tensor&&dep_alloc_ready),.cmd_ready(v_ready),.cmd_client(cmd_client),.cmd_op(cmd_op),.cmd_tag(cmd_tag),.operand_a(a),.operand_b(b),.done_valid(v_done),.done_ready(v_done_ready),.done_client(v_client),.done_tag(v_tag),.done_status(v_status),.done_result(v_result),.busy());
tessera_tensor_tile #(.CLIENT_W(CLIENT_W),.TAG_W(TAG_W),.DATA_W(DATA_W),.ACC_W(ACC_W),.OP_W(OP_W)) tensor(.clk(clk),.rst_n(rst_n),.cmd_valid(cmd_valid&&select_tensor&&dep_alloc_ready),.cmd_ready(t_ready),.cmd_client(cmd_client),.cmd_op(cmd_op),.cmd_tag(cmd_tag),.operand_a($signed(a)),.operand_b($signed(b)),.accumulator(acc),.done_valid(t_done),.done_ready(t_done_ready),.done_client(t_client),.done_tag(t_tag),.done_status(t_status),.done_result(t_result),.busy());
assign v_done_ready=!select_done&&fifo_in_ready; assign t_done_ready=select_done&&fifo_in_ready;
logic select_done; logic fifo_in_valid,fifo_in_ready; logic [CLIENT_W-1:0] done_client; logic [TAG_W-1:0] done_tag; logic [1:0] done_status; logic [ACC_W-1:0] done_result;
assign select_done=t_done; assign fifo_in_valid=v_done||t_done; assign done_client=t_done?t_client:v_client; assign done_tag=t_done?t_tag:v_tag; assign done_status=t_done?t_status:v_status; assign done_result=t_done?t_result:{{(ACC_W-DATA_W){v_result[DATA_W-1]}},v_result};
tessera_dependency_scoreboard #(.N_CLIENTS(N_CLIENTS),.TAG_W(TAG_W),.CLIENT_W(CLIENT_W),.DEPTH(DEP_TAGS)) deps(.clk(clk),.rst_n(rst_n),.alloc_valid(cmd_valid&&cmd_ready),.alloc_ready(dep_alloc_ready),.alloc_client(cmd_client),.alloc_tag(cmd_tag),.complete_valid(completion_valid&&completion_ready),.complete_client(completion_client),.complete_tag(completion_tag),.complete_known(dep_known),.duplicate_alloc(dep_dup),.unknown_completion(dep_unknown),.live_bitmap(dep_live),.live_count(dep_count));
assign rec_in={done_client,done_tag,done_status,done_result}; assign {completion_client,completion_tag,completion_status,completion_result}=rec_out; assign completion_occupancy=q_count;
tessera_command_fifo #(.WIDTH(REC_W),.DEPTH(DEPTH),.COUNT_W(COUNT_W)) result_fifo(.clk(clk),.rst_n(rst_n),.in_valid(fifo_in_valid),.in_ready(fifo_in_ready),.in_data(rec_in),.out_valid(completion_valid),.out_ready(completion_ready),.out_data(rec_out),.occupancy(q_count));
endmodule
